def parse_student(line):
    fields = line.rstrip("\n").split(",")
    if len(fields) != 3:
        raise ValueError("record must contain id, name and mark")

    student_id, name, mark_text = fields
    mark = int(mark_text)
    if not 0 <= mark <= 100:
        raise ValueError("mark is outside 0 to 100")

    return {"id": student_id, "name": name, "mark": mark}

def find_student(filename, target_id):
    with open(filename, "r", encoding="utf-8") as file:
        for line in file:
            student = parse_student(line)
            if student["id"] == target_id:
                return student
            if student["id"] > target_id:
                break  # later keys will be even larger
    return None

RECORD_SIZE = 32

def read_record(filename, record_number):
    if record_number < 0:
        raise ValueError("record number cannot be negative")

    with open(filename, "rb") as file:
        file.seek(record_number * RECORD_SIZE)
        raw_record = file.read(RECORD_SIZE)

    if len(raw_record) != RECORD_SIZE:
        return None
    return raw_record.decode("utf-8").rstrip()

def load_marks(filename):
    marks = []
    try:
        with open(filename, "r", encoding="utf-8") as file:
            for line_number, line in enumerate(file, start=1):
                marks.append(int(line.strip()))
    except FileNotFoundError:
        print(f"Cannot open {filename}: file not found")
        return None
    except ValueError:
        print(f"Invalid integer on line {line_number}")
        return None
    else:
        return marks

def input_mark():
    while True:
        try:
            mark = int(input("Mark (0 to 100): "))
        except ValueError:
            print("Enter a whole number.")
            continue

        if 0 <= mark <= 100:
            return mark
        print("Mark must be from 0 to 100.")
